INSERT INTO `v1_4c06921a24521962f469d06257a46a22a48fb0d5b1de9a32fccae813b8e65b93` VALUES (0, 10, 1, 82021, 11, 1, 1, "それでも……適性など踏み越えて、\n己の道を突き進むのが冒険者です。\n一度決めたことを、\n曲げるわけには参りません……！", 82, 0, 0);
